@app.post("/admin/audit/purge", dependencies=[Depends(require_admin)])
def purge_audit(older_than_days: int = 2555, session: Session = Depends(db.get_db)):
    import datetime
    from sqlalchemy import delete
    from ledgerlite.models import AuditEntry
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=older_than_days)
    result = session.execute(delete(AuditEntry).where(AuditEntry.timestamp < cutoff))
    session.commit()
    return {"purged": result.rowcount}


